type dispatcherEventFilesChanged struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventFilesChanged) Dispatch(e dpapp.EventFilesChanged) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventFilesChanged) DispatchCtx(
	ctx context.Context, e dpapp.EventFilesChanged,
) error {
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventFilesChanged JSON: %w", err)
	}
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, EvSubjFilesChanged, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", EvSubjFilesChanged, err)
	}
	return nil
}

