type dispatcherEventUploadStarted struct {
	s   *Server
	ctx context.Context
}

func (d dispatcherEventUploadStarted) Dispatch(e dpapp.EventUploadStarted) error {
	return d.DispatchCtx(d.ctx, e)
}

func (d dispatcherEventUploadStarted) DispatchCtx(
	ctx context.Context, e dpapp.EventUploadStarted,
) error {
	if e.Tab == "" {
		return errors.New("EventUploadStarted.Tab must not be empty")
	}
	j, err := json.Marshal(e)
	if err != nil {
		return fmt.Errorf("marshaling EventUploadStarted JSON: %w", err)
	}
	subj := "upload.started." + subject.Encode(string(e.Tab))
	err = d.s.messageBroker.Publish(ctx, d.s.messageBrokerMetrics, subj, j)
	if err != nil {
		return fmt.Errorf("publishing subject %q: %w", subj, err)
	}
	return nil
}
